/**
 * Writes a SQL data migration that brings an existing database up to date with
 * src/db/content (lesson text) and src/db/lesson-videos.json (videos).
 *
 * Safety rules, so admin edits are never overwritten:
 *  - Lesson text is replaced only while the lesson still has the original outline placeholder.
 *  - A video is attached only if the lesson has no video, or still points at the same generated file
 *    (in which case only its length and size are refreshed).
 *
 * Usage: npx drizzle-kit generate --custom --name <name>   (creates an empty file + journal entry)
 *        npx tsx scripts/gen-content-migration.ts drizzle/<that file>.sql
 */
import { readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { courseContent, lessonSlug } from "../src/db/content";
import lessonVideos from "../src/db/lesson-videos.json";

const out = process.argv[2];
if (!out) throw new Error("Pass the migration file path to write.");

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const lessonOf = (course: string, lesson: string) =>
  `FROM "course_modules" AS m, "courses" AS c WHERE l."module_id" = m."id" AND m."course_id" = c."id" AND c."slug" = ${q(course)} AND l."slug" = ${q(lesson)}`;

const statements: string[] = [];

for (const c of courseContent) {
  for (const l of c.lessons) {
    statements.push(
      `UPDATE "lessons" AS l SET "summary" = ${q(l.summary)}, "body" = ${q(l.body)}, "checklist" = ${q(JSON.stringify(l.checklist))}::jsonb, "est_minutes" = ${l.minutes}\n` +
        `${lessonOf(c.slug, lessonSlug(l.title))} AND l."body" LIKE 'This lesson introduces %';`,
    );
  }
}

const videos = lessonVideos as unknown as {
  credit: string;
  courses: Record<string, Record<string, { videoUrl: string; videoPoster: string; videoCaptions: string; videoDurationSec: number; videoSizeBytes: number }>>;
};
for (const [course, lessons] of Object.entries(videos.courses)) {
  for (const [lesson, v] of Object.entries(lessons)) {
    statements.push(
      `UPDATE "lessons" AS l SET "video_url" = ${q(v.videoUrl)}, "video_poster" = ${q(v.videoPoster)}, "video_captions" = ${q(v.videoCaptions)}, ` +
        `"video_duration_sec" = ${v.videoDurationSec}, "video_size_bytes" = ${v.videoSizeBytes}, "video_credit" = ${q(videos.credit)}\n` +
        `${lessonOf(course, lesson)} AND (l."video_url" IS NULL OR l."video_url" = ${q(v.videoUrl)});`,
    );
  }
}

// Library files rebuilt from the lessons: keep the size shown before download accurate.
const filesDir = path.join(process.cwd(), "public/files");
for (const f of readdirSync(filesDir)) {
  statements.push(`UPDATE "resources" SET "size_bytes" = ${statSync(path.join(filesDir, f)).size} WHERE "file_url" = ${q(`/files/${f}`)};`);
}

writeFileSync(
  out,
  "-- Generated by scripts/gen-content-migration.ts: full lessons and narrated videos.\n" +
    "-- Never overwrites lessons or videos that an admin has edited.\n" +
    statements.join("\n--> statement-breakpoint\n") +
    "\n",
);
console.log(`Wrote ${statements.length} statements to ${out}`);
